(function(root){
'use strict';
const PROTOCOL='bldc-1';
function validTelemetry(d){return d?.type==='telemetry'&&d.protocol===PROTOCOL&&d.firmware==='native-bldc'&&typeof d.power_ready==='boolean'&&typeof d.armed==='boolean'&&typeof d.motor_enabled==='boolean'&&['vbus_v','vmotor_v','feed_current_a','electrical_hz','max_percent','max_run_ms'].every(k=>Number.isFinite(d[k]));}
function controlState(d,fresh,busy){const ready=fresh&&validTelemetry(d);return {arm:ready&&!busy&&d.power_ready&&!d.armed&&!d.motor_enabled,start:ready&&!busy&&d.armed&&!d.motor_enabled,power:ready&&!busy&&!d.armed&&!d.motor_enabled&&d.vmotor_v<1,settings:ready&&!busy,speedMax:ready?Math.min(8,d.max_percent):8};}
class BldcClient{
 constructor({onTelemetry=()=>{},onError=()=>{},clock=()=>Date.now(),timeout=6000}={}){this.onTelemetry=onTelemetry;this.onError=onError;this.clock=clock;this.timeout=timeout;this.pending=new Map();this.last=null;this.seen=0;this.nextId=0;this.generation=0;this.chain=Promise.resolve();this.port=null;this.reader=null;this.buffer='';this.dropping=false;this.closing=false;}
 receive(line){let d;try{d=JSON.parse(line);}catch{return;}if(d.protocol!==PROTOCOL)return;if(d.type==='ack'){const p=this.pending.get(d.id);if(p){clearTimeout(p.timer);this.pending.delete(d.id);d.ok?p.resolve(d):p.reject(Error(d.error||'Board rejected command'));}}else if(validTelemetry(d)){this.last=d;this.seen=this.clock();this.onTelemetry(d);}}
 feed(text){for(const ch of text){if(ch==='\n'){if(!this.dropping)this.receive(this.buffer.trim());this.buffer='';this.dropping=false;}else if(!this.dropping){this.buffer+=ch;if(this.buffer.length>4096){this.buffer='';this.dropping=true;}}}}
 fresh(){return this.last!==null&&this.clock()-this.seen<1500;}
 write(data,{generation=this.generation,urgent=false}={}){const port=this.port;const job=this.chain.catch(()=>{}).then(async()=>{if(!port?.writable||port!==this.port)throw Error('Board disconnected');if(!urgent&&generation!==this.generation)throw Error('Command cancelled by Stop');const writer=port.writable.getWriter();try{await writer.write(new TextEncoder().encode(JSON.stringify(data)+'\n'));}finally{writer.releaseLock();}});this.chain=job;return job;}
 send(cmd,fields={}){if(!this.port)return Promise.reject(Error('Connect the board first'));if(cmd==='stop')this.generation++;const id=++this.nextId;return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{this.pending.delete(id);reject(Error('Board did not acknowledge '+cmd));},this.timeout);this.pending.set(id,{resolve,reject,timer});this.write({...fields,cmd,id},{urgent:cmd==='stop'}).catch(e=>{clearTimeout(timer);this.pending.delete(id);reject(e);});});}
 heartbeat(){if(this.port&&this.fresh())this.write({cmd:'heartbeat'}).catch(()=>{});}
 async attach(port){this.port=port;this.closing=false;this.last=null;this.seen=0;this.buffer='';this.dropping=false;await port.open({baudRate:115200});await port.setSignals({dataTerminalReady:true,requestToSend:false});this.reader=port.readable.getReader();this.reading=this.readLoop();await this.send('hello');await this.send('status');}
 async readLoop(){const decoder=new TextDecoder();try{while(this.reader){const {value,done}=await this.reader.read();if(done)break;this.feed(decoder.decode(value,{stream:true}));}}catch(e){if(!this.closing)this.onError(e);}finally{this.reader?.releaseLock();this.reader=null;if(!this.closing)this.onError(Error('USB connection ended'));}}
 async close(){if(this.closing)return;this.closing=true;try{if(this.port?.writable&&this.last)await this.send('stop').catch(()=>{});if(this.reader)await this.reader.cancel();if(this.reading)await this.reading;await this.chain.catch(()=>{});if(this.port)await this.port.close();}finally{this.port=null;this.last=null;this.seen=0;this.generation++;for(const p of this.pending.values()){clearTimeout(p.timer);p.reject(Error('Disconnected'));}this.pending.clear();}}
}
const api={PROTOCOL,validTelemetry,controlState,BldcClient};if(typeof module!=='undefined')module.exports=api;
if(!root.document)return;
const $=id=>document.getElementById(id);let busy=false,connecting=false,points=[];
const message=text=>{$('message').textContent=text;};
const client=new BldcClient({onTelemetry:render,onError:async e=>{message(e.message);await client.close();update();}});
function update(){const d=client.last,c=controlState(d,client.fresh(),busy);$('connect').disabled=connecting;$('connect').textContent=client.port?'Disconnect':'Connect motor';$('arm').disabled=!c.arm;$('start').disabled=!c.start;$('request9').disabled=!c.power;$('stop').disabled=!client.port;$('speed').disabled=!c.settings;$('duration').disabled=!c.settings||!!d?.motor_enabled;$('speed').max=c.speedMax;if(!client.port){$('state').textContent='Disconnected';$('runStatus').textContent='Connect to begin.';}else if(!client.fresh()){$('state').textContent='Waiting for BLDC telemetry';$('runStatus').textContent='No fresh compatible telemetry; motor controls disabled.';}}
function render(d){$('state').textContent=d.state.replaceAll('_',' ');$('identity').textContent=`${d.board} · ${d.device_id}`;$('voltage').textContent=d.vmotor_v.toFixed(2);$('current').textContent=d.feed_current_a.toFixed(3);$('frequency').textContent=d.electrical_hz.toFixed(1);$('powerHint').textContent=`PD input ${d.vbus_v.toFixed(2)} V · ${d.power_ready?'motor supply ready':'motor supply not ready'}`;$('motionHint').textContent=`${d.fg_edges} FG edges · ${d.motor_enabled?'drive enabled':'drive disabled'}`;$('runStatus').textContent=d.reason;$('runProgress').value=d.remaining_ms;$('runProgress').max=Number($('duration').value);$('firmwareStatus').textContent=`${d.firmware_version} · ${d.firmware_build}`;$('powerStatus').textContent=d.power_ready?'9 V motor rail ready. Arm, then Start.':d.vmotor_v<1?'Motor rail is off. Request 9 V, then turn SW4 ON.':'Set SW4 OFF before requesting 9 V.';const colors={RUNNING:'#75efd0',STARTING:'#64e0ee',WAITING_FOR_ARM:'#f5bf63',POWER_ON_DISARMED:'#f5bf63',FAULT:'#ff6c78',POWER_NOT_READY:'#ff6c78',LOGIC_ON_MOTOR_POWER_OFF:'#6d9bff',BOOT:'#6d9bff',NEGOTIATING:'#6d9bff'};$('ledDot').style.background=colors[d.led]||'#536173';$('led').textContent='LED '+d.led.toLowerCase().replaceAll('_',' ');points.push({t:Date.now(),v:d.feed_current_a});points=points.filter(p=>p.t>Date.now()-30000).slice(-200);update();draw();}
function draw(){const canvas=$('history'),r=canvas.getBoundingClientRect(),ratio=root.devicePixelRatio||1;canvas.width=Math.max(1,r.width*ratio);canvas.height=Math.max(1,r.height*ratio);const g=canvas.getContext('2d');if(!g)return;g.scale(ratio,ratio);const w=r.width,h=r.height,left=40,bottom=25,top=15,hi=Math.max(.15,...points.map(p=>p.v*1.2)),now=Date.now();g.font='11px system-ui';g.lineWidth=1;for(let i=0;i<=3;i++){let y=top+(h-top-bottom)*i/3;g.strokeStyle='#273445';g.beginPath();g.moveTo(left,y);g.lineTo(w,y);g.stroke();g.fillStyle='#91a3b8';g.fillText((hi*(1-i/3)).toFixed(2),0,y+4);}g.strokeStyle='#75efd0';g.lineWidth=2;g.beginPath();points.forEach((p,i)=>{const x=left+(p.t-(now-30000))/30000*(w-left),y=top+(1-p.v/hi)*(h-top-bottom);i?g.lineTo(x,y):g.moveTo(x,y);});g.stroke();g.fillStyle='#91a3b8';g.fillText('−30 s',left,h-4);g.fillText('now',w-27,h-4);}
async function action(cmd,fields={},text){busy=true;update();try{await client.send(cmd,fields);if(text)message(text);}catch(e){message(e.message);}finally{busy=false;update();}}
$('connect').onclick=async()=>{if(client.port){await client.close();update();return;}connecting=true;update();try{const port=await navigator.serial.requestPort();await client.attach(port);message('Connected. Verify motor power, then Arm and Start.');client.heartbeat();}catch(e){message(e.name==='NotFoundError'?'No board selected.':e.message+' Use the BLDC firmware and close other serial monitors.');await client.close();}finally{connecting=false;update();}};
$('arm').onclick=()=>action('arm',{},'Armed for 30 seconds. Press Start for one timed run.');
$('start').onclick=()=>action('start',{percent:Number($('speed').value),duration_ms:Number($('duration').value)},'Timed run requested. Stop is always available.');
$('stop').onclick=()=>action('stop',{},'Stopped and disarmed.');
$('request9').onclick=()=>action('set_pd_voltage',{voltage:9},'9 V requested. Turn SW4 ON when ready.');
$('speed').oninput=()=>{$('speedValue').textContent=$('speed').value+'%';};
$('speed').onchange=()=>{if(client.last?.motor_enabled)void action('set_speed',{percent:Number($('speed').value)},'Speed command updated.');};
function stopForPage(){if(client.port)void client.send('stop').catch(()=>{});}
root.addEventListener('blur',stopForPage);root.addEventListener('pagehide',stopForPage);document.addEventListener('visibilitychange',()=>{if(document.hidden)stopForPage();});root.addEventListener('keydown',e=>{if((e.code==='Space'&&!['INPUT','SELECT','BUTTON'].includes(e.target.tagName))||e.code==='Escape'){e.preventDefault();stopForPage();}});
setInterval(()=>{if(!document.hidden)client.heartbeat();update();},300);new ResizeObserver(draw).observe($('history'));
if(!('serial' in navigator)||!root.isSecureContext){$('connect').disabled=true;message('Web Serial needs desktop Chrome or Edge on HTTPS or localhost.');}else navigator.serial.addEventListener('disconnect',e=>{if(e.target===client.port||e.port===client.port){message('Board disconnected.');void client.close().then(update);}});
})(typeof window==='undefined'?globalThis:window);
